@Override
    public UserAccountVO queryUserAccountByUserId(String userId, UserAccountTypeEnum accountType) {
        UserLoginAccountDOKey key = new UserLoginAccountDOKey();
        key.setUserId(userId);
        key.setAccountType(accountType.name());
        UserLoginAccountDO userLoginAccountDO = userLoginAccountMapper.selectByPrimaryKey(key);
        if (userLoginAccountDO == null) {
            return null;
        }
        UserAccountVO userAccountVO = new UserAccountVO();
        userAccountVO.setUserId(userId);
        userAccountVO.setAccountType(accountType);
        userAccountVO.setAccountNo(userLoginAccountDO.getAccountNo());
        userAccountVO.setPassword(userLoginAccountDO.getPassword());
        userAccountVO.setAppCode(userLoginAccountDO.getAppCode());
        return userAccountVO;
    }

private StaffThirdpartyInfo getEmpNo(AppVO app) {
        if (app != null && app.getUserId() != null) {
            UserAccountVO userAccountVO = userInfrastructure.queryUserAccountByUserId(app.getUserId().toString(), UserAccountTypeEnum.WECOM_USERID);
            if (userAccountVO != null) {
                DialogStaffE dialogStaffE = dialogStaffRepository.getStaffByStaffId(userAccountVO.getAccountNo());
                if (dialogStaffE != null) {
                    return JSON.parseObject(dialogStaffE.getStaffThirdpartyInfo(), StaffThirdpartyInfo.class);
                }
            }
        }
        return null;
    }

